  "evidence_summary": {
    "supported_causes": [
      {
        "cause": "OOMKilled (容器因内存超限被系统强制杀死)",
        "evidence": [
          "kubectl describe pod: 容器状态中明确显示 `Reason: OOMKilled`, `Exit Code: 137` (137 = 128 + SIGKILL, Linux 标准 OOM 退出码)",
          "kubectl get pod yaml: `containerStatuses.app.reason = CrashLoopBackOff`, `exitCode = 137`, `restarts = 12`",
          "预采集 Metrics (execute_pod_promql): `last_terminated_reason = OOMKilled`, `waiting_reason = CrashLoopBackOff`, `restarts_total = 12`",
          "kubectl events: `Warning BackOff` 事件持续 49 分钟 (x181 over 49m)，表明容器反复崩溃重启",
          "kubectl previous logs: 崩溃前的日志显示 HTTP /work 端点连续进行内存分配 (memory allocation progression from 2 MiB to 48 MiB)，每次请求约增加 2 MiB，共约 24 次请求，内存持续增长直到触发 OOM"
        ]
      }
    ],
    "refuted_causes": [
      {
        "cause": "镜像拉取失败 (ImagePullBackOff)",
        "evidence": "容器已运行并处理了 HTTP 请求 (previous logs 显示成功分配内存)，且 describe 中 containerStatuses 无 image pull 相关 error"
      },
      {
        "cause": "配置错误/启动命令失败 (Error/Completed)",
        "evidence": "Exit Code 137 而非 1/2 或 139 (SIGSEGV)，且 previous logs 显示容器已正常运行并处理请求，并非启动即失败"
      },
      {
        "cause": "Liveness/Readiness Probe 失败导致的重启",
        "evidence": "describe 中 Reason 明确为 OOMKilled 而非 ProbeFailed；退出码 137 指向内核 OOM Killer，非应用主动退出"
      }
    ],
    "gaps": [
      "kubectl get pod yaml 的输出中未显示 resource.requests/limits 的具体数值，无法精确判断内存限制阈值；但 OOMKilled + Exit 137 已充分证明容器超出了其分配的内存配额",
      "previous logs 显示内存从 2 MiB 逐步增长到 48 MiB，但未记录最终的 RSS/AllocBytes 峰值与 limit 的对比关系"
    ],
    "conclusion": "CrashLoopBackOff 的直接原因是 OOMKilled。容器因在 /work 端点处理请求时持续分配内存 (2→48 MiB)，超出容器内存限制后被内核 OOM Killer 强制终止 (Exit 137)，导致 Kubelet 反复重启并进入 BackOff 退避循环 (49 分钟内 181 次)。证据链完整：describe (Reason=OOMKilled, ExitCode=137) + previous logs (内存增长模式) + events (BackOff) + Metrics (last_terminated_reason=OOMKilled)。"
  }
}
